public static class ProductApiPage
{
 public static string Html()=>Membership.Shell("Yapay zekâ API ayarı","""
 <section class="member-card provider-page provider-api"><p class="member-eyebrow">SAĞLAYICI YÖNETİMİ</p><h1>Yapay zekâ API</h1><p class="provider-lead">Tek bağlantı, tüm ürünler. Anahtarınızı bir kez kaydedin; ürün açıklamaları aynı bağlantıyla hazırlansın.</p><nav class="provider-tabs" aria-label="Sağlayıcı türü"><a href="/admin/mail">E-posta</a><a href="/admin/sms">SMS</a><a href="/admin/api" aria-current="page">API</a></nav>
 <div class="provider-status" id="api-provider-status"><span class="provider-status-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14" rx="4"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4M9 9h6v6H9z"/></svg></span><div class="provider-status-main"><div class="provider-status-title"><strong>OpenAI</strong><span id="api-badge" class="provider-status-pill">Kontrol ediliyor</span></div><p id="api-state" role="status">Bağlantı durumu alınıyor…</p></div></div>
 <form id="api-form"><label class="provider-key-label">API anahtarı<input id="api-key" type="password" autocomplete="new-password" minlength="20" maxlength="300" placeholder="sk-…" required></label><small class="provider-help">Anahtar gizli tutulur. Değiştirmek için yeni anahtarınızı girin; boş bırakmak kayıtlı anahtarı silmez.</small><div class="member-actions provider-save-actions"><button id="api-save" class="member-button" type="submit">API anahtarını kaydet</button><button id="api-remove" class="member-secondary provider-danger" type="button" hidden>Bağlantıyı kaldır</button></div></form>
 <p id="api-result" role="status" aria-live="polite"></p><details class="provider-info"><summary>Bağlantı ve kullanım bilgisi</summary><p>Anahtar sunucuda şifrelenir. Ürün açıklamaları ve canlı destek çevirisi aynı bağlantıyı kullanır. API kullanımı sağlayıcınızın tarifesine tabidir.</p><p>Bağlantı kaldırıldığında yapay zekâ alanı gizlenir; önceden kaydettiğiniz açıklamalar korunur.</p></details><div class="member-actions provider-footer"><a class="member-secondary" href="/admin?tab=settings">Ayarlara dön</a><a class="member-secondary" href="/admin?tab=products">Ürünlere git</a></div></section>
 <script>
 (()=>{const key=document.getElementById('api-key'),save=document.getElementById('api-save'),remove=document.getElementById('api-remove'),result=document.getElementById('api-result'),state=document.getElementById('api-state');let working=false;
 async function load(){const r=await fetch('/api/admin/ai-settings',{cache:'no-store'});if(!r.ok)throw Error('Bağlantı ayarı alınamadı. Oturumunuzu kontrol edin.');const b=await r.json();state.textContent=b.ready?'Kayıtlı anahtar tüm ürünlerde kullanılır.':'Açıklama hazırlamak için API anahtarınızı ekleyin.';document.getElementById('api-badge').textContent=b.ready?'Anahtar kayıtlı':'Bağlantı yok';document.getElementById('api-provider-status').dataset.ready=String(b.ready);remove.hidden=!b.ready;save.textContent=b.ready?'API anahtarını değiştir':'API anahtarını kaydet';}
 async function change(body){if(working)return;working=true;save.disabled=true;remove.disabled=true;result.textContent='Kaydediliyor…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const cr=await fetch('/api/security/csrf',{signal:controller.signal,cache:'no-store'});if(!cr.ok)throw Error('Oturumunuzu yenileyin.');const token=(await cr.json()).token;const r=await fetch('/api/admin/ai-settings',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','X-INOKSKAR-CSRF':token},body:JSON.stringify(body)});const b=await r.json();if(!r.ok)throw Error(b.error||'Bağlantı kaydedilemedi.');key.value='';await load();result.textContent=body.remove?'API bağlantısı kaldırıldı.':'API anahtarı kaydedildi. Yeni ürünlerde açıklama otomatik hazırlanır.';}catch(e){result.textContent=e.name==='AbortError'?'İşlem zaman aşımına uğradı. Tekrar deneyin.':e.message;}finally{clearTimeout(timer);working=false;save.disabled=false;remove.disabled=false;}}
 document.getElementById('api-form').onsubmit=e=>{e.preventDefault();void change({apiKey:key.value.trim(),remove:false});};remove.onclick=()=>{if(confirm('API bağlantısı kaldırılsın mı? Canlı destek çevirisi de kapanır; kayıtlı açıklamalar korunur.'))void change({remove:true});};load().catch(e=>{state.textContent=e.message;});})();
 </script>
 """,false,true).Replace("</head>","<link rel='stylesheet' href='/provider-pages.css?v=providers-1'></head>",StringComparison.Ordinal);
}
